 {
  if(b.Jammed&&b.Kind!="CovertCyno")return "Destination beacon is cyno jammed.";bool covert=kind=="CovertPortal"||CombatHulls.Get(Player.CombatHull).Role=="BlackOps";bool industrial=kind=="IndustrialPortal"||CombatHulls.Get(Player.CombatHull).Role is "CapitalIndustrial" or "JumpFreighter";
