  double mass=passengers.Sum(w=>Targets.First(t=>t.Id==w.Id).Profile!.Stat("mass"));int fuel=conduit?(int)Math.Ceiling((Player.EliteBattleship?Player.Stat("conduitJumpDriveConsumptionAmount"):920)*BeaconDistance(SystemId,b.System)):(int)Math.Ceiling(mass*(d.Kind=="CovertPortal"?2e-7:d.Kind=="IndustrialPortal"?1e-9:1.5e-9)*BeaconDistance(SystemId,b.System)*240);if(ItemCount("jump_fuel",false)<fuel){Say("Bridge requires "+fuel+" transit fuel.");return false;}if(conduit&&Player.Cap<Player.MaxCap*(Player.EliteBattleship?(float)Player.Stat("jumpDriveCapacitorNeed"):.7f))return false;
