 public bool UseWormhole(){if(InAbyssF)return false;if(SelectedId.StartsWith("wf:"))return TransitConnectionF();var t=Selected;var h=Wormholes.FirstOrDefault(h=>h.Id==t?.Id&&(h.A==SystemId||h.B==SystemId));if(Docked||t==null||h==null||h.RemainingMass<=0||Vector3.Distance(t.Position,Player.Position)>2500||SpecialDockLocked&&!Player.HasSpecial("Mass")||Cloaked)return false;double mass=Player.Stat("mass");if(mass>h.MaxShipMass||h.RecentJumps>=2&&h.Polarization>0){Say("Fracture mass limit or polarization blocks passage.");return false;}h.RemainingMass=Math.Max(0,h.RemainingMass-mass);h.RecentJumps++;h.Polarization=300;string dest=h.A==SystemId?h.B:h.A;PreserveMassTransit=true;LeaveSpecialGrid(true);LeaveSupportGrid(true);RecoverProbesForTransit();SystemId=dest;EnterGrid("special_range",false);RestoreSpecialGrid();PreserveMassTransit=false;Player.Position=new(2400,0,0);Say("Fracture transit; remaining mass "+h.RemainingMass.ToString("0")+" kg.");return true;}
